def mark_legacy_invoices(apps, schema_editor):
    """Счета, выставленные при оформлении до этапа 3, продолжают скачиваться (ТЗ §10.5)."""
    apps.get_model("orders", "Invoice").objects.update(legacy=True)


def clamp_cart_quantities(apps, schema_editor):
    CartItem = apps.get_model("orders", "CartItem")
    CartItem.objects.filter(quantity__gt=999).update(quantity=999)
    CartItem.objects.filter(quantity__lt=1).delete()


